package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type expr interface {
	eval(items []evalItem, env *evalEnv) ([]evalItem, error)
}

type evalEnv struct {
	cfg *config
}

type evalItem struct {
	Node      *yaml.Node
	FileIndex int
	Format    string
}

type literalExpr struct {
	node *yaml.Node
}

func (e *literalExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		out = append(out, evalItem{Node: cloneNode(e.node), FileIndex: item.FileIndex, Format: item.Format})
	}
	if len(items) == 0 {
		out = append(out, evalItem{Node: cloneNode(e.node), FileIndex: 0, Format: "yaml"})
	}
	return out, nil
}

type identifierExpr struct {
	name string
}

func (e *identifierExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		switch e.name {
		case "fileIndex", "fi":
			out = append(out, evalItem{Node: newNumberNode(strconv.Itoa(item.FileIndex)), FileIndex: item.FileIndex, Format: item.Format})
		default:
			return nil, fmt.Errorf("unsupported identifier: %s", e.name)
		}
	}
	return out, nil
}

type pathStepKind int

const (
	pathField pathStepKind = iota
	pathIndex
	pathIter
)

type pathStep struct {
	Kind  pathStepKind
	Field string
	Index int
}

type pathExpr struct {
	Steps []pathStep
}

func (e *pathExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	if len(e.Steps) == 0 {
		return cloneItems(items), nil
	}
	current := cloneItems(items)
	for _, step := range e.Steps {
		next := make([]evalItem, 0)
		for _, item := range current {
			results, err := applyPathStep(item, step)
			if err != nil {
				return nil, err
			}
			next = append(next, results...)
		}
		current = next
	}
	return current, nil
}

type pipelineExpr struct {
	Left  expr
	Right expr
}

func (e *pipelineExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	left, err := e.Left.eval(items, env)
	if err != nil {
		return nil, err
	}
	return e.Right.eval(left, env)
}

type arrayExpr struct {
	Inner expr
}

func (e *arrayExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	if len(items) == 0 {
		return []evalItem{{Node: newSequenceNode(nil), FileIndex: 0, Format: "yaml"}}, nil
	}
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		inner, err := e.Inner.eval([]evalItem{cloneItem(item)}, env)
		if err != nil {
			return nil, err
		}
		seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, result := range inner {
			seq.Content = append(seq.Content, cloneNode(result.Node))
		}
		out = append(out, evalItem{Node: seq, FileIndex: item.FileIndex, Format: item.Format})
	}
	return out, nil
}

type selectExpr struct {
	Predicate expr
}

func (e *selectExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		pred, err := e.Predicate.eval([]evalItem{cloneItem(item)}, env)
		if err != nil {
			return nil, err
		}
		if anyTruthy(pred) {
			out = append(out, cloneItem(item))
		}
	}
	return out, nil
}

type compareExpr struct {
	Left  expr
	Right expr
}

func (e *compareExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		leftItems, err := e.Left.eval([]evalItem{cloneItem(item)}, env)
		if err != nil {
			return nil, err
		}
		rightItems, err := e.Right.eval([]evalItem{cloneItem(item)}, env)
		if err != nil {
			return nil, err
		}
		var leftNode, rightNode *yaml.Node
		if len(leftItems) > 0 {
			leftNode = leftItems[0].Node
		}
		if len(rightItems) > 0 {
			rightNode = rightItems[0].Node
		}
		out = append(out, evalItem{
			Node:      newBoolNode(nodesEqual(leftNode, rightNode)),
			FileIndex: item.FileIndex,
			Format:    item.Format,
		})
	}
	return out, nil
}

type mergeExpr struct {
	Left  expr
	Right expr
}

func (e *mergeExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	left, err := e.Left.eval(cloneItems(items), env)
	if err != nil {
		return nil, err
	}
	right, err := e.Right.eval(cloneItems(items), env)
	if err != nil {
		return nil, err
	}
	if len(left) == 0 && len(right) == 0 {
		return nil, nil
	}
	if len(left) == 0 {
		return cloneItems(right), nil
	}
	if len(right) == 0 {
		return cloneItems(left), nil
	}
	count := len(left)
	if len(right) < count {
		count = len(right)
	}
	out := make([]evalItem, 0, count)
	for i := 0; i < count; i++ {
		out = append(out, evalItem{
			Node:      mergeNodes(left[i].Node, right[i].Node),
			FileIndex: left[i].FileIndex,
			Format:    left[i].Format,
		})
	}
	return out, nil
}

type assignExpr struct {
	Target *pathExpr
	Value  expr
}

func (e *assignExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		rhs, err := e.Value.eval([]evalItem{cloneItem(item)}, env)
		if err != nil {
			return nil, err
		}
		var valueNode *yaml.Node
		if len(rhs) > 0 {
			valueNode = rhs[0].Node
		} else {
			valueNode = newNullNode()
		}
		root := cloneNode(item.Node)
		changed, err := assignPath(&root, e.Target.Steps, valueNode)
		if err != nil {
			return nil, err
		}
		if !changed {
			root = cloneNode(item.Node)
		}
		out = append(out, evalItem{Node: root, FileIndex: item.FileIndex, Format: item.Format})
	}
	return out, nil
}

type loadExpr struct {
	Path string
}

func (e *loadExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	if env.cfg.securityDisableFileOps {
		return nil, fmt.Errorf("file operations have been disabled")
	}
	loaded, err := loadOnePath(e.Path, env.cfg.inputFormat, -1, nil)
	if err != nil {
		return nil, err
	}
	return loaded, nil
}

type strenvExpr struct {
	Name string
}

func (e *strenvExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	if env.cfg.securityDisableEnvOps {
		return nil, fmt.Errorf("env operations have been disabled")
	}
	value := os.Getenv(e.Name)
	out := make([]evalItem, 0, len(items))
	if len(items) == 0 {
		out = append(out, evalItem{Node: newStringNode(value), FileIndex: 0, Format: "yaml"})
		return out, nil
	}
	for _, item := range items {
		out = append(out, evalItem{Node: newStringNode(value), FileIndex: item.FileIndex, Format: item.Format})
	}
	return out, nil
}

type reduceMergeExpr struct{}

func (e *reduceMergeExpr) eval(items []evalItem, env *evalEnv) ([]evalItem, error) {
	merged := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for _, item := range items {
		merged = mergeNodes(merged, item.Node)
	}
	format := "yaml"
	if len(items) > 0 {
		format = items[0].Format
	}
	return []evalItem{{Node: merged, FileIndex: 0, Format: format}}, nil
}

func applyPathStep(item evalItem, step pathStep) ([]evalItem, error) {
	node := item.Node
	switch step.Kind {
	case pathField:
		return applyFieldStep(item, node, step.Field)
	case pathIndex:
		return applyIndexStep(item, node, step.Index), nil
	case pathIter:
		return applyIterStep(item, node), nil
	default:
		return nil, fmt.Errorf("unsupported path step")
	}
}

func applyFieldStep(item evalItem, node *yaml.Node, field string) ([]evalItem, error) {
	node = derefDocument(node)
	switch {
	case node == nil:
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}, nil
	case node.Kind == yaml.MappingNode:
		if child, ok := mapGet(node, field); ok {
			return []evalItem{{Node: child, FileIndex: item.FileIndex, Format: item.Format}}, nil
		}
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}, nil
	case node.Kind == yaml.SequenceNode:
		if idx, err := strconv.ParseInt(field, 10, 64); err == nil {
			return applyIndexStep(item, node, int(idx)), nil
		} else {
			return nil, fmt.Errorf("cannot index array with '%s' (%v)", field, err)
		}
	case node.Kind == yaml.ScalarNode && isNullNode(node):
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}, nil
	default:
		return nil, nil
	}
}

func applyIndexStep(item evalItem, node *yaml.Node, index int) []evalItem {
	node = derefDocument(node)
	switch {
	case node == nil:
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}
	case node.Kind == yaml.SequenceNode:
		if index >= 0 && index < len(node.Content) {
			return []evalItem{{Node: node.Content[index], FileIndex: item.FileIndex, Format: item.Format}}
		}
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}
	case node.Kind == yaml.MappingNode:
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}
	case node.Kind == yaml.ScalarNode && isNullNode(node):
		return []evalItem{{Node: newNullNode(), FileIndex: item.FileIndex, Format: item.Format}}
	default:
		return nil
	}
}

func applyIterStep(item evalItem, node *yaml.Node) []evalItem {
	node = derefDocument(node)
	if node == nil || node.Kind != yaml.SequenceNode {
		return nil
	}
	out := make([]evalItem, 0, len(node.Content))
	for _, child := range node.Content {
		out = append(out, evalItem{Node: child, FileIndex: item.FileIndex, Format: item.Format})
	}
	return out
}

func assignPath(root **yaml.Node, steps []pathStep, value *yaml.Node) (bool, error) {
	if len(steps) == 0 {
		*root = cloneNode(value)
		return true, nil
	}
	current := *root
	if current == nil || isNullNode(current) {
		switch steps[0].Kind {
		case pathField:
			current = newMapNode()
		case pathIndex:
			current = newSequenceNode(nil)
		default:
			return false, nil
		}
		*root = current
	}
	for i := 0; i < len(steps)-1; i++ {
		step := steps[i]
		next := steps[i+1]
		var ok bool
		current, ok = descendOrCreate(current, step, next)
		if !ok {
			return false, nil
		}
	}
	last := steps[len(steps)-1]
	return setAtStep(current, last, value), nil
}

func descendOrCreate(current *yaml.Node, step pathStep, next pathStep) (*yaml.Node, bool) {
	current = derefDocument(current)
	if current == nil {
		return nil, false
	}
	switch step.Kind {
	case pathField:
		if current.Kind != yaml.MappingNode {
			return nil, false
		}
		child, ok := mapGet(current, step.Field)
		if !ok || child == nil || isNullNode(child) {
			child = containerFor(next)
			mapSet(current, step.Field, child)
		}
		if child.Kind == yaml.ScalarNode && !isNullNode(child) {
			return nil, false
		}
		if child.Kind == yaml.ScalarNode && isNullNode(child) {
			child = containerFor(next)
			mapSet(current, step.Field, child)
		}
		return child, true
	case pathIndex:
		if current.Kind != yaml.SequenceNode {
			return nil, false
		}
		for len(current.Content) <= step.Index {
			current.Content = append(current.Content, newNullNode())
		}
		child := current.Content[step.Index]
		if child == nil || isNullNode(child) {
			child = containerFor(next)
			current.Content[step.Index] = child
		}
		if child.Kind == yaml.ScalarNode && !isNullNode(child) {
			return nil, false
		}
		if child.Kind == yaml.ScalarNode && isNullNode(child) {
			child = containerFor(next)
			current.Content[step.Index] = child
		}
		return child, true
	default:
		return nil, false
	}
}

func setAtStep(current *yaml.Node, step pathStep, value *yaml.Node) bool {
	current = derefDocument(current)
	if current == nil {
		return false
	}
	switch step.Kind {
	case pathField:
		if current.Kind != yaml.MappingNode {
			return false
		}
		mapSet(current, step.Field, cloneNode(value))
		return true
	case pathIndex:
		if current.Kind != yaml.SequenceNode {
			return false
		}
		for len(current.Content) <= step.Index {
			current.Content = append(current.Content, newNullNode())
		}
		current.Content[step.Index] = cloneNode(value)
		return true
	default:
		return false
	}
}

func containerFor(next pathStep) *yaml.Node {
	switch next.Kind {
	case pathField:
		return newMapNode()
	case pathIndex:
		return newSequenceNode(nil)
	default:
		return newNullNode()
	}
}

func mergeNodes(left, right *yaml.Node) *yaml.Node {
	left = derefDocument(left)
	right = derefDocument(right)
	if left == nil {
		return cloneNode(right)
	}
	if right == nil {
		return cloneNode(left)
	}
	if left.Kind == yaml.MappingNode && right.Kind == yaml.MappingNode {
		out := cloneNode(left)
		for i := 0; i < len(right.Content); i += 2 {
			key := right.Content[i].Value
			rhs := right.Content[i+1]
			if lhs, ok := mapGet(out, key); ok {
				mapSet(out, key, mergeNodes(lhs, rhs))
			} else {
				mapSet(out, key, cloneNode(rhs))
			}
		}
		return out
	}
	return cloneNode(right)
}

func nodesEqual(a, b *yaml.Node) bool {
	return reflect.DeepEqual(nodeToComparable(a), nodeToComparable(b))
}

func nodeToComparable(node *yaml.Node) any {
	node = derefDocument(node)
	if node == nil {
		return nil
	}
	switch node.Kind {
	case yaml.MappingNode:
		out := make([]any, 0, len(node.Content))
		for i := 0; i < len(node.Content); i += 2 {
			out = append(out, node.Content[i].Value)
			out = append(out, nodeToComparable(node.Content[i+1]))
		}
		return out
	case yaml.SequenceNode:
		out := make([]any, 0, len(node.Content))
		for _, child := range node.Content {
			out = append(out, nodeToComparable(child))
		}
		return out
	case yaml.ScalarNode:
		switch node.Tag {
		case "!!null":
			return nil
		case "!!bool":
			return node.Value == "true"
		case "!!int":
			if v, err := strconv.ParseInt(node.Value, 10, 64); err == nil {
				return v
			}
		case "!!float":
			if v, err := strconv.ParseFloat(node.Value, 64); err == nil {
				return v
			}
		}
		return node.Value
	default:
		return node.Value
	}
}

func anyTruthy(items []evalItem) bool {
	for _, item := range items {
		if isTruthy(item.Node) {
			return true
		}
	}
	return false
}

func isTruthy(node *yaml.Node) bool {
	node = derefDocument(node)
	if node == nil {
		return false
	}
	if node.Kind != yaml.ScalarNode {
		return true
	}
	if isNullNode(node) {
		return false
	}
	if node.Tag == "!!bool" && node.Value == "false" {
		return false
	}
	return true
}

func cloneNode(node *yaml.Node) *yaml.Node {
	if node == nil {
		return nil
	}
	copy := *node
	if len(node.Content) > 0 {
		copy.Content = make([]*yaml.Node, len(node.Content))
		for i, child := range node.Content {
			copy.Content[i] = cloneNode(child)
		}
	}
	return &copy
}

func cloneItem(item evalItem) evalItem {
	return evalItem{Node: cloneNode(item.Node), FileIndex: item.FileIndex, Format: item.Format}
}

func cloneItems(items []evalItem) []evalItem {
	out := make([]evalItem, 0, len(items))
	for _, item := range items {
		out = append(out, cloneItem(item))
	}
	return out
}

func derefDocument(node *yaml.Node) *yaml.Node {
	if node == nil {
		return nil
	}
	if node.Kind == yaml.DocumentNode {
		if len(node.Content) == 0 {
			return nil
		}
		return node.Content[0]
	}
	return node
}

func newNullNode() *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
}

func newStringNode(s string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}
}

func newBoolNode(v bool) *yaml.Node {
	if v {
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "true"}
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "false"}
}

func newNumberNode(v string) *yaml.Node {
	tag := "!!int"
	if strings.ContainsAny(v, ".eE") {
		tag = "!!float"
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: tag, Value: v}
}

func newMapNode() *yaml.Node {
	return &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
}

func newSequenceNode(content []*yaml.Node) *yaml.Node {
	return &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Content: content}
}

func isNullNode(node *yaml.Node) bool {
	return node != nil && node.Kind == yaml.ScalarNode && (node.Tag == "!!null" || node.Value == "null")
}

func mapGet(node *yaml.Node, key string) (*yaml.Node, bool) {
	if node == nil || node.Kind != yaml.MappingNode {
		return nil, false
	}
	for i := 0; i < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			return node.Content[i+1], true
		}
	}
	return nil, false
}

func mapSet(node *yaml.Node, key string, value *yaml.Node) {
	if node == nil || node.Kind != yaml.MappingNode {
		return
	}
	for i := 0; i < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			node.Content[i+1] = value
			return
		}
	}
	node.Content = append(node.Content,
		&yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: key},
		value,
	)
}

func loadOnePath(path string, inputFormat string, fileIndex int, stdinData *[]byte) ([]evalItem, error) {
	var data []byte
	var err error
	format := detectInputFormat(path, inputFormat)
	if path == "-" {
		if stdinData != nil && *stdinData != nil {
			data = *stdinData
		} else {
			data, err = io.ReadAll(os.Stdin)
			if err != nil {
				return nil, err
			}
			if stdinData != nil {
				*stdinData = data
			}
		}
	} else {
		data, err = os.ReadFile(path)
		if err != nil {
			return nil, err
		}
	}
	if format == "json" {
		node, err := parseJSONNode(data)
		if err != nil {
			return nil, err
		}
		return []evalItem{{Node: node, FileIndex: fileIndex, Format: "json"}}, nil
	}
	docs, err := parseYAMLNodes(data)
	if err != nil {
		return nil, err
	}
	out := make([]evalItem, 0, len(docs))
	if len(docs) == 0 {
		out = append(out, evalItem{Node: nil, FileIndex: fileIndex, Format: "yaml"})
		return out, nil
	}
	for _, doc := range docs {
		out = append(out, evalItem{Node: doc, FileIndex: fileIndex, Format: "yaml"})
	}
	return out, nil
}

func detectInputFormat(path string, inputFormat string) string {
	switch normalizeFormat(inputFormat) {
	case "json":
		return "json"
	case "yaml":
		return "yaml"
	}
	if path != "-" && strings.EqualFold(filepath.Ext(path), ".json") {
		return "json"
	}
	return "yaml"
}

func normalizeFormat(value string) string {
	switch strings.ToLower(value) {
	case "", "auto", "a":
		return "auto"
	case "yaml", "y", "kyaml", "ky":
		return "yaml"
	case "json", "j":
		return "json"
	default:
		return strings.ToLower(value)
	}
}

func parseYAMLNodes(data []byte) ([]*yaml.Node, error) {
	if len(data) == 0 {
		return []*yaml.Node{nil}, nil
	}
	dec := yaml.NewDecoder(bytes.NewReader(data))
	out := make([]*yaml.Node, 0)
	for {
		var doc yaml.Node
		err := dec.Decode(&doc)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		if len(doc.Content) == 0 {
			out = append(out, nil)
		} else {
			out = append(out, doc.Content[0])
		}
	}
	return out, nil
}

func parseJSONNode(data []byte) (*yaml.Node, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	node, err := parseJSONValue(dec)
	if err != nil {
		return nil, err
	}
	if err := consumeJSONEOF(dec); err != nil {
		return nil, err
	}
	return node, nil
}

func consumeJSONEOF(dec *json.Decoder) error {
	var extra any
	if err := dec.Decode(&extra); err == io.EOF {
		return nil
	} else if err != nil {
		return nil
	}
	return nil
}

func parseJSONValue(dec *json.Decoder) (*yaml.Node, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := tok.(type) {
	case json.Delim:
		switch v {
		case '{':
			node := newMapNode()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("invalid json object key")
				}
				value, err := parseJSONValue(dec)
				if err != nil {
					return nil, err
				}
				node.Content = append(node.Content,
					&yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: key},
					value,
				)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return node, nil
		case '[':
			node := newSequenceNode(nil)
			for dec.More() {
				value, err := parseJSONValue(dec)
				if err != nil {
					return nil, err
				}
				node.Content = append(node.Content, value)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return node, nil
		default:
			return nil, fmt.Errorf("invalid json delimiter")
		}
	case string:
		return newStringNode(v), nil
	case json.Number:
		return newNumberNode(v.String()), nil
	case bool:
		return newBoolNode(v), nil
	case nil:
		return newNullNode(), nil
	default:
		return nil, fmt.Errorf("unsupported json value")
	}
}

type tokenKind int

const (
	tokenEOF tokenKind = iota
	tokenDot
	tokenIdent
	tokenString
	tokenNumber
	tokenLBracket
	tokenRBracket
	tokenLParen
	tokenRParen
	tokenPipe
	tokenAssign
	tokenEq
	tokenStar
)

type token struct {
	kind tokenKind
	text string
}

type parser struct {
	src    string
	tokens []token
	pos    int
}

func parseExpression(input string) (expr, error) {
	normalized := strings.Join(strings.Fields(input), " ")
	if matchedReduce(normalized) {
		return &reduceMergeExpr{}, nil
	}
	tokens, err := tokenize(input)
	if err != nil {
		return nil, err
	}
	p := &parser{src: input, tokens: tokens}
	if p.peek().kind == tokenEOF {
		return nil, nil
	}
	ex, err := p.parsePipeline()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tokenEOF {
		return nil, fmt.Errorf("unexpected token: %s", p.peek().text)
	}
	return ex, nil
}

func matchedReduce(normalized string) bool {
	normalized = strings.ReplaceAll(normalized, " ;", ";")
	normalized = strings.ReplaceAll(normalized, "; ", ";")
	return strings.HasPrefix(normalized, ". as $") &&
		strings.Contains(normalized, " ireduce ({};. * $") &&
		strings.HasSuffix(normalized, ")")
}

func tokenize(input string) ([]token, error) {
	var tokens []token
	for i := 0; i < len(input); {
		switch ch := input[i]; {
		case ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r':
			i++
		case ch == '.':
			tokens = append(tokens, token{kind: tokenDot, text: "."})
			i++
		case ch == '[':
			tokens = append(tokens, token{kind: tokenLBracket, text: "["})
			i++
		case ch == ']':
			tokens = append(tokens, token{kind: tokenRBracket, text: "]"})
			i++
		case ch == '(':
			tokens = append(tokens, token{kind: tokenLParen, text: "("})
			i++
		case ch == ')':
			tokens = append(tokens, token{kind: tokenRParen, text: ")"})
			i++
		case ch == '|':
			tokens = append(tokens, token{kind: tokenPipe, text: "|"})
			i++
		case ch == '*':
			tokens = append(tokens, token{kind: tokenStar, text: "*"})
			i++
		case ch == '=':
			if i+1 < len(input) && input[i+1] == '=' {
				tokens = append(tokens, token{kind: tokenEq, text: "=="})
				i += 2
			} else {
				tokens = append(tokens, token{kind: tokenAssign, text: "="})
				i++
			}
		case ch == '"':
			j := i + 1
			var buf strings.Builder
			for j < len(input) {
				if input[j] == '\\' && j+1 < len(input) {
					esc := input[j+1]
					switch esc {
					case '"', '\\', '/':
						buf.WriteByte(esc)
					case 'n':
						buf.WriteByte('\n')
					case 'r':
						buf.WriteByte('\r')
					case 't':
						buf.WriteByte('\t')
					case '0':
						buf.WriteByte(0)
					default:
						buf.WriteByte(esc)
					}
					j += 2
					continue
				}
				if input[j] == '"' {
					break
				}
				buf.WriteByte(input[j])
				j++
			}
			if j >= len(input) || input[j] != '"' {
				return nil, fmt.Errorf("unterminated string")
			}
			tokens = append(tokens, token{kind: tokenString, text: buf.String()})
			i = j + 1
		case ch >= '0' && ch <= '9':
			j := i + 1
			for j < len(input) && ((input[j] >= '0' && input[j] <= '9') || input[j] == '.' || input[j] == 'e' || input[j] == 'E' || input[j] == '+' || input[j] == '-') {
				j++
			}
			tokens = append(tokens, token{kind: tokenNumber, text: input[i:j]})
			i = j
		case isIdentStart(ch):
			j := i + 1
			for j < len(input) && isIdentPart(input[j]) {
				j++
			}
			tokens = append(tokens, token{kind: tokenIdent, text: input[i:j]})
			i = j
		case ch == '$':
			j := i + 1
			for j < len(input) && isIdentPart(input[j]) {
				j++
			}
			tokens = append(tokens, token{kind: tokenIdent, text: input[i:j]})
			i = j
		default:
			return nil, fmt.Errorf("unexpected character: %c", ch)
		}
	}
	tokens = append(tokens, token{kind: tokenEOF})
	return tokens, nil
}

func isIdentStart(ch byte) bool {
	return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch == '_'
}

func isIdentPart(ch byte) bool {
	return isIdentStart(ch) || (ch >= '0' && ch <= '9')
}

func (p *parser) peek() token {
	return p.tokens[p.pos]
}

func (p *parser) next() token {
	tok := p.tokens[p.pos]
	if p.pos < len(p.tokens)-1 {
		p.pos++
	}
	return tok
}

func (p *parser) parsePipeline() (expr, error) {
	left, err := p.parseAssignment()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokenPipe {
		p.next()
		right, err := p.parseAssignment()
		if err != nil {
			return nil, err
		}
		left = &pipelineExpr{Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseAssignment() (expr, error) {
	left, err := p.parseMerge()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tokenAssign {
		p.next()
		target, ok := left.(*pathExpr)
		if !ok {
			return nil, fmt.Errorf("left hand side of assignment must be a path")
		}
		if p.peek().kind == tokenEOF {
			return nil, fmt.Errorf("'=' expects 2 args but there is 1")
		}
		right, err := p.parseAssignment()
		if err != nil {
			return nil, err
		}
		return &assignExpr{Target: target, Value: right}, nil
	}
	return left, nil
}

func (p *parser) parseMerge() (expr, error) {
	left, err := p.parseComparison()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokenStar {
		p.next()
		right, err := p.parseComparison()
		if err != nil {
			return nil, err
		}
		left = &mergeExpr{Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseComparison() (expr, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tokenEq {
		p.next()
		right, err := p.parsePrimary()
		if err != nil {
			return nil, err
		}
		return &compareExpr{Left: left, Right: right}, nil
	}
	return left, nil
}

func (p *parser) parsePrimary() (expr, error) {
	switch tok := p.peek(); tok.kind {
	case tokenDot:
		return p.parsePath()
	case tokenLBracket:
		p.next()
		inner, err := p.parsePipeline()
		if err != nil {
			return nil, err
		}
		if p.peek().kind != tokenRBracket {
			return nil, fmt.Errorf("bad expression, could not find matching `]`")
		}
		p.next()
		return &arrayExpr{Inner: inner}, nil
	case tokenString:
		p.next()
		return &literalExpr{node: newStringNode(tok.text)}, nil
	case tokenNumber:
		p.next()
		return &literalExpr{node: newNumberNode(tok.text)}, nil
	case tokenIdent:
		return p.parseIdentifierOrCall()
	case tokenLParen:
		p.next()
		inner, err := p.parsePipeline()
		if err != nil {
			return nil, err
		}
		if p.peek().kind != tokenRParen {
			return nil, fmt.Errorf("missing )")
		}
		p.next()
		return inner, nil
	default:
		return nil, fmt.Errorf("unexpected token: %s", tok.text)
	}
}

func (p *parser) parseIdentifierOrCall() (expr, error) {
	tok := p.next()
	switch tok.text {
	case "true":
		return &literalExpr{node: newBoolNode(true)}, nil
	case "false":
		return &literalExpr{node: newBoolNode(false)}, nil
	case "null":
		return &literalExpr{node: newNullNode()}, nil
	}
	if p.peek().kind == tokenLParen {
		p.next()
		switch tok.text {
		case "select":
			inner, err := p.parsePipeline()
			if err != nil {
				return nil, err
			}
			if p.peek().kind != tokenRParen {
				return nil, fmt.Errorf("missing )")
			}
			p.next()
			return &selectExpr{Predicate: inner}, nil
		case "strenv":
			arg := p.next()
			var name string
			switch arg.kind {
			case tokenIdent, tokenString:
				name = arg.text
			default:
				return nil, fmt.Errorf("invalid strenv argument")
			}
			if p.peek().kind != tokenRParen {
				return nil, fmt.Errorf("missing )")
			}
			p.next()
			return &strenvExpr{Name: name}, nil
		case "load":
			arg := p.next()
			if arg.kind != tokenString {
				return nil, fmt.Errorf("invalid load argument")
			}
			if p.peek().kind != tokenRParen {
				return nil, fmt.Errorf("missing )")
			}
			p.next()
			return &loadExpr{Path: arg.text}, nil
		default:
			return nil, fmt.Errorf("unsupported function: %s", tok.text)
		}
	}
	return &identifierExpr{name: tok.text}, nil
}

func (p *parser) parsePath() (expr, error) {
	p.next()
	steps := make([]pathStep, 0)
	for {
		switch p.peek().kind {
		case tokenIdent:
			steps = append(steps, pathStep{Kind: pathField, Field: p.next().text})
		case tokenLBracket:
			p.next()
			switch p.peek().kind {
			case tokenRBracket:
				p.next()
				steps = append(steps, pathStep{Kind: pathIter})
			case tokenNumber:
				number := p.next().text
				if p.peek().kind != tokenRBracket {
					return nil, fmt.Errorf("bad expression, could not find matching `]`")
				}
				p.next()
				index, err := strconv.Atoi(number)
				if err != nil {
					return nil, err
				}
				steps = append(steps, pathStep{Kind: pathIndex, Index: index})
			default:
				return nil, fmt.Errorf("bad expression, could not find matching `]`")
			}
		default:
			return &pathExpr{Steps: steps}, nil
		}
		if p.peek().kind == tokenDot {
			p.next()
			continue
		}
		if p.peek().kind == tokenLBracket {
			continue
		}
		return &pathExpr{Steps: steps}, nil
	}
}

